import itertools
from pysat import SAT

# Let's try to find an all-interval series of size 13
# We need a permutation of 0..12 such that differences are 1..12

# Let's use a SAT solver approach
from pysat.formula import CNF
from pysat.solvers import Glucose3

# We'll encode variables: x[i][v] = 1 if position i has value v
# and d[i][diff] = 1 if difference between position i and i+1 is diff

n = 13
values = list(range(n))
diffs = list(range(1, n))

# Create variable mapping
var = {}
idx = 1

# x[i][v]
x = {}
for i in range(n):
    x[i] = {}
    for v in values:
        x[i][v] = idx
        var[idx] = f"x_{i}_{v}"
        idx += 1

# d[i][diff]
d = {}
for i in range(n-1):
    d[i] = {}
    for diff in diffs:
        d[i][diff] = idx
        var[idx] = f"d_{i}_{diff}"
        idx += 1

total_vars = idx - 1
print(f"Total variables: {total_vars}")

# Build CNF
cnf = CNF()

# Each position has exactly one value
for i in range(n):
    # At least one
    cnf.add_clause([x[i][v] for v in values])
    # At most one (pairwise)
    for v1 in range(n):
        for v2 in range(v1+1, n):
            cnf.add_clause([-x[i][v1], -x[i][v2]])

# Each value used exactly once (already covered by above + permutation constraint)
# But let's add: each value appears at least once
for v in values:
    cnf.add_clause([x[i][v] for i in range(n)])

# Each difference appears exactly once
for diff in diffs:
    # At least one
    cnf.add_clause([d[i][diff] for i in range(n-1)])
    # At most one
    for i1 in range(n-1):
        for i2 in range(i1+1, n-1):
            cnf.add_clause([-d[i1][diff], -d[i2][diff]])

# Each position has exactly one difference
for i in range(n-1):
    cnf.add_clause([d[i][diff] for diff in diffs])
    for diff1 in range(1, n):
        for diff2 in range(diff1+1, n):
            cnf.add_clause([-d[i][diff1], -d[i][diff2]])

# Link x and d: if x[i][a] and x[i+1][b] then d[i][|a-b|]
for i in range(n-1):
    for a in values:
        for b in values:
            diff = abs(a - b)
            if diff > 0:
                cnf.add_clause([-x[i][a], -x[i+1][b], d[i][diff]])

print(f"Total clauses: {len(cnf.clauses)}")

# Solve
solver = Glucose3(cnf)
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    # Extract solution
    solution = [None] * n
    for i in range(n):
        for v in values:
            if model[x[i][v]-1] > 0:
                solution[i] = v
                break
    print(f"Solution: {solution}")

    # Verify
    diffs_found = [abs(solution[i+1] - solution[i]) for i in range(n-1)]
    print(f"Diffs: {diffs_found}")
    print(f"Sorted diffs: {sorted(diffs_found)}")
    print(f"Expected: {list(range(1, n))}")
else:
    print("UNSATISFIABLE")

